-- Removes benchmark-only rows generated by generate_data.sql, leaving the
-- dev database back at its seed.sql state.
DELETE FROM raw_material WHERE name LIKE 'Benchmark Material %';
-- All seeded customer_order rows have matching order_item rows (see
-- seed.sql); benchmark-generated customer_order rows do not, since
-- generate_data.sql deliberately never inserts order_item.
DELETE FROM customer_order WHERE order_id NOT IN (SELECT order_id FROM order_item);
